@Override
  public int port() {
    String value = System.getenv(STATSD_SERVER_PORT_ENV_NAME);
    if (StringUtils.isEmpty(value)) {
      return 0;
    }
    try {
      return Integer.parseInt(value);
    } catch (Throwable ex) {
      logger.warn(
          String.format(
              "Failed to parse environment value for %s: %s", STATSD_SERVER_PORT_ENV_NAME, value),
          ex);
      return 0;
    }
  }

